var report=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("Docs/Validation/CropPastelChanges.json"));foreach(var entry in report["materials"]){var m=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>((string)entry["pastel"]);m.name=(string)entry["name"];UnityEditor.EditorUtility.SetDirty(m);}UnityEditor.AssetDatabase.SaveAssets();return new{renamed=report["materials"].Count()};
